package indicator

import (
	"github.com/charmbracelet/lipgloss"

	"github.com/anthnel/devdesk/internal/ui/theme"
)

// Color returns the theme colour that paints s. The theme globals are read at
// call time because ApplyTheme reassigns them.
func Color(s State) lipgloss.Color {
	switch s {
	case Running:
		return theme.ColorActivityRunning
	case Failed:
		return theme.ColorActivityFailed
	case Suspended, Restarting:
		return theme.ColorActivitySuspended
	case Queued, Done, Cancelled, Skipped, Unknown:
		return theme.ColorActivityNeutral
	default: // Idle
		return theme.ColorText
	}
}

// Style returns a foreground-only style for s; the datatable paints the
// background (Rule 122).
func Style(s State) lipgloss.Style {
	return lipgloss.NewStyle().Foreground(Color(s))
}

var glyphs = map[State]string{
	Queued: "◴", Failed: "⊗", Suspended: "◐", Restarting: "◕",
	Done: "◉", Cancelled: "⊘", Skipped: "⊖", Unknown: "◌",
}

const (
	runningOn  = "●"
	runningOff = "○"
)

// States returns every state but Idle, in declaration order.
func States() []State { return append([]State(nil), states...) }

// Glyph returns the one-rune glyph of s; on is the blink phase (Running only).
// Idle has no glyph and yields an empty string.
func Glyph(s State, on bool) string {
	if s == Running {
		if on {
			return runningOn
		}
		return runningOff
	}
	return glyphs[s]
}

// Animated reports whether s blinks.
func Animated(s State) bool { return s == Running }

// String returns the lowercase name of s.
func (s State) String() string {
	if n, ok := names[s]; ok {
		return n
	}
	return "invalid"
}

// Activity is everything that can be true of one row at once.
type Activity struct {
	Running, Queued, Failed bool  // Failed = a remembered failure
	Observed                State // computed by the view; Idle if none
	styles := theme.DefaultTableStyles()
	if item, ok := m.Selected(); ok {
		if m.cfg.SelectedStyles != nil {
			styles = m.cfg.SelectedStyles(item)
		}
		// Busy wins over whatever the view asked for, and this is the one place
		// it can be said: the highlight is applied to the joined row, so a
		// colour inside it would close with a reset and end the highlight
		// mid-row (see render.go). An `exited` container being removed is not
		// exited-and-that-is-that — the state is what the action is about to
		// change, so the transition is the newer fact.
		if _, busy := m.busyLabel(item); busy {
			styles.Selected = theme.TableStylesForState("busy").Selected
		}
	}
	// The background is the signal: only the plain "normal" look carries
	// ColorTableLineSelected, so this is true exactly when no view-level state or
	// busy override took over the row — see cellStyle for what it changes.
	m.preserveColumnColors = styles.Selected.GetBackground() == theme.ColorTableLineSelected
	// Pin the selected row to the full content width. Column widths are counted
	// in cells, and a Nerd Font icon does not always render as wide as it
	// counts, so the highlight otherwise stops short of the right border by
	// however much the row's icons disagreed. Padding to a width the row can
	// never exceed is a no-op when they agree.
	if m.width > 2 {
		styles.Selected = styles.Selected.Width(m.width - 2)
	}
	m.setStyles(styles)
}

